use rigorix_engine::precondition::application::PreconditionCheckInput;
use rigorix_engine::precondition::domain::{Precondition, PreconditionError, PreconditionOutcome};
use rigorix_engine::precondition::infrastructure::{
    PreconditionRun, PreconditionRunner, ProcessPreconditionRunner,
};
use serde_json::json;

/// The domain maximum (#1081): these are must-pass checks. `/bin/sh -c 'exit 0'`
/// finishing is not in doubt, but the 5s default is a wall-clock budget sharing
/// the machine with the rest of the suite, so a loaded host could report
/// `Timeout` and fail a test whose subject is exit-code mapping.
const TEST_TIMEOUT_MS: u64 = 60_000;

fn precondition(id: &str, command: Vec<&str>) -> Precondition {
    let mut parsed: Precondition = serde_json::from_value(json!({
        "id": id,
        "match": { "tool": "payment_execute" },
        "command": command
    }))
    .expect("precondition parses");
    parsed.timeout_ms = TEST_TIMEOUT_MS;
    parsed
}

fn input() -> PreconditionCheckInput {
    PreconditionCheckInput {
        precondition_id: "p1".to_string(),
        execution_id: uuid::Uuid::nil(),
        step: "pay".to_string(),
        tool: "payment_execute".to_string(),
        parameters: json!({ "beneficiary": "acct-1" }),
    }
}

fn runner() -> ProcessPreconditionRunner {
    ProcessPreconditionRunner::new(std::env::temp_dir())
}

#[test]
fn test_preconditionrunner_is_defined() {
    let runner = ProcessPreconditionRunner::new("/workspace/agent-writable");
    assert_eq!(
        runner.workspace_root(),
        std::path::Path::new("/workspace/agent-writable")
    );
}

#[test]
fn test_preconditionrunner_is_object_safe() {
    let runner: Box<dyn PreconditionRunner> =
        Box::new(ProcessPreconditionRunner::new("/workspace/agent-writable"));
    let _ = &runner;
}

#[test]
fn test_run_outcome_taxonomy_distinguishes_failed_from_error() {
    let failed = PreconditionRun {
        outcome: PreconditionOutcome::Failed,
        exit_code: Some(3),
        stdout: None,
        check_writable: None,
        authority_writable: None,
        check_digest: None,
        authority_digest: None,
    };
    let error = PreconditionRun {
        outcome: PreconditionOutcome::Error,
        exit_code: None,
        stdout: None,
        check_writable: None,
        authority_writable: None,
        check_digest: None,
        authority_digest: None,
    };
    assert!(failed.outcome.refuses());
    assert!(error.outcome.refuses());
    assert_ne!(failed.outcome, error.outcome);
}

#[tokio::test]
async fn argv_exit_codes_are_mapped() {
    let pass = runner()
        .run(
            &precondition("p1", vec!["/bin/sh", "-c", "exit 0"]),
            &input(),
        )
        .await
        .expect("run");
    assert_eq!(pass.outcome, PreconditionOutcome::Passed);
    assert_eq!(pass.exit_code, Some(0));

    let fail = runner()
        .run(
            &precondition("p1", vec!["/bin/sh", "-c", "exit 4"]),
            &input(),
        )
        .await
        .expect("run");
    assert_eq!(fail.outcome, PreconditionOutcome::Failed);
    assert_eq!(fail.exit_code, Some(4));
}

#[tokio::test]
async fn json_stdin_and_env_are_provided() {
    let run = runner()
        .run(
            &precondition(
                "p1",
                vec![
                    "/bin/sh",
                    "-c",
                    "read -r line || exit 9; [ \"$RIGORIX_TOOL\" = payment_execute ] || exit 9",
                ],
            ),
            &input(),
        )
        .await
        .expect("run");
    assert_eq!(run.outcome, PreconditionOutcome::Passed);
}

#[tokio::test]
async fn command_inside_workspace_is_refused() {
    let workspace = tempfile::tempdir().expect("tempdir");
    let check = workspace.path().join("check.sh");
    std::fs::write(&check, "#!/bin/sh\nexit 0\n").expect("write");
    let runner = ProcessPreconditionRunner::new(workspace.path());
    let error = runner
        .run(&precondition("p1", vec![check.to_str().unwrap()]), &input())
        .await
        .expect_err("trust boundary");
    assert!(matches!(error, PreconditionError::TrustBoundary { .. }));
}

/// #1081: virtual clock. The subject is "the runner honours the budget", not
/// "this machine took >100ms to get here". The child sleeps far longer than any
/// real CI stall, so the timer cannot lose the race, and the wait is advanced
/// instantly rather than burning a real 100ms plus a real `sleep` process inside
/// a suite that already runs thousands of tests.
#[tokio::test(start_paused = true)]
async fn timeout_refuses_never_passes() {
    let mut slow = precondition("p1", vec!["/bin/sh", "-c", "sleep 3600"]);
    slow.timeout_ms = 100;
    let timeout = runner().run(&slow, &input()).await.expect_err("timeout");
    assert!(matches!(timeout, PreconditionError::Timeout { .. }));
    assert!(!timeout.is_retriable());
}

/// Fault injection for the case above: a check that finishes inside its budget
/// is judged on its exit code. Without this, a runner that refused everything as
/// `Timeout` would still satisfy the timeout test.
#[tokio::test]
async fn a_check_inside_its_budget_is_judged_by_its_exit_code() {
    let mut fast = precondition("p1", vec!["/bin/sh", "-c", "exit 0"]);
    fast.timeout_ms = 60_000;
    let run = runner().run(&fast, &input()).await.expect("run");
    assert_eq!(run.outcome, PreconditionOutcome::Passed);
}

#[tokio::test]
async fn spawn_failure_refuses_never_passes() {
    let spawn = runner()
        .run(
            &precondition("p1", vec!["/nonexistent/rigorix-check-xyz"]),
            &input(),
        )
        .await
        .expect_err("spawn");
    assert!(matches!(spawn, PreconditionError::Spawn { .. }));
    assert!(!spawn.is_retriable());
}

// ---------------------------------------------------------------------------
// #1653 — the check's environment is an allowlist, and the two sets are by name
// ---------------------------------------------------------------------------

/// The audit's executed proof, turned into a test: a check that dumps its environment.
///
/// It held `RIGORIX_HMAC_KEY` — so a check script, or any library it loads, could **sign
/// envelopes**, the key that makes evidence verifiable — plus the operator's registry and
/// model-provider tokens, `SSH_AUTH_SOCK` (the agent that reaches their repositories), and the full
/// parent environment.
///
/// The assertions are by **name**, not by looking for a pattern: a rename of `RIGORIX_HMAC_KEY`
/// would silently pass a "no secrets" scan, and the whole point is that the four names the runner
/// sets are the only `RIGORIX_*` a check may see.
#[tokio::test]
async fn the_check_sees_an_allowlist_and_never_the_signing_key() {
    // Planted in *this* process, so the test proves the child did not inherit them rather than
    // proving the parent happened not to have them.
    // SAFETY: the test process is a dedicated harness; the variables are set before any check runs.
    unsafe {
        std::env::set_var("RIGORIX_HMAC_KEY", "planted-signing-key");
        std::env::set_var("GITHUB_TOKEN", "planted-registry-token");
        std::env::set_var("ANTHROPIC_API_KEY", "planted-model-token");
        std::env::set_var("SSH_AUTH_SOCK", "/tmp/planted-agent.sock");
    }

    // `capture_output` is opt-in (SpanPrivacy), and this test is the reason it exists: without it
    // stdout is discarded and the dump proves nothing.
    let mut dump = precondition("p1", vec!["/usr/bin/env"]);
    dump.capture_output = true;
    let run = runner()
        .run(&dump, &input())
        .await
        .expect("run /usr/bin/env");

    let env = run.stdout.clone().unwrap_or_default();
    let names: Vec<&str> = env
        .lines()
        .filter_map(|line| line.split_once('=').map(|(name, _)| name))
        .collect();

    // Present: the four facts the runner sets, and the PATH a check needs to find a program.
    for required in [
        "RIGORIX_PRECONDITION_ID",
        "RIGORIX_EXECUTION_ID",
        "RIGORIX_STEP_NAME",
        "RIGORIX_TOOL",
        "PATH",
    ] {
        assert!(
            names.contains(&required),
            "the check must see `{required}`; it saw: {names:?}"
        );
    }

    // Absent: the key that signs evidence, the operator's credentials, and the agent.
    for forbidden in [
        "RIGORIX_HMAC_KEY",
        "GITHUB_TOKEN",
        "ANTHROPIC_API_KEY",
        "SSH_AUTH_SOCK",
    ] {
        assert!(
            !names.contains(&forbidden),
            "the check inherited `{forbidden}` — a precondition that can sign or ride the operator's \
             credentials is the finding, not a convenience: {names:?}"
        );
    }

    // Exhaustive on the RIGORIX_ namespace: the four facts, and nothing else.
    let mut rigorix_names: Vec<&str> = names
        .iter()
        .copied()
        .filter(|name| name.starts_with("RIGORIX_"))
        .collect();
    rigorix_names.sort_unstable();
    assert_eq!(
        rigorix_names,
        vec![
            "RIGORIX_EXECUTION_ID",
            "RIGORIX_PRECONDITION_ID",
            "RIGORIX_STEP_NAME",
            "RIGORIX_TOOL",
        ],
        "the RIGORIX_ namespace a check sees is a list, and this is the list"
    );
}
